import{_ as i,a0 as n,w as p,s as d,I as s,x as t,a1 as o,A as r,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const H=JSON.parse('{"title":"怎樣在 Linux 下用 SSH 搭建個人文件服務器 | LCTT x X-CMD","titleTemplate":false,"description":"怎樣在 Linux 下用 SSH 搭建個人文件服務器 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣在 Linux 下用 SSH 搭建個人文件服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣在 Linux 下用 SSH 搭建個人文件服務器 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200323 How to create a personal file server with SSH on Linux","title":"怎樣在 Linux 下用 SSH 搭建個人文件服務器","tag":"202005","desc":""},"relativePath":"202005/20200323 How to create a personal file server with SSH on Linux.md","filePath":"[post].md"}'),u={name:"202005/20200323 How to create a personal file server with SSH on Linux.md"};function f(m,e,S,g,h,x){const l=n("Link");return p(),d("div",null,[e[31]||(e[31]=s("h1",{id:"怎樣在-linux-下用-ssh-搭建個人文件服務器",tabindex:"-1"},[t("怎樣在 Linux 下用 SSH 搭建個人文件服務器 "),s("a",{class:"header-anchor",href:"#怎樣在-linux-下用-ssh-搭建個人文件服務器","aria-label":"Permalink to “怎樣在 Linux 下用 SSH 搭建個人文件服務器”"},"​")],-1)),e[32]||(e[32]=s("blockquote",null,[s("p",null,"通過 SSH 連接遠程 Linux 系統很簡單。下面是教程。")],-1)),e[33]||(e[33]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202005/27/120338v62cakrqnccpjckk.jpg",alt:""})],-1)),s("p",null,[e[1]||(e[1]=t("樹莓派是一個有用且價格低廉的家庭服務器，可用於很多事情。我的樹莓派最常用來做",-1)),o(l,{href:"https://opensource.com/article/18/3/print-server-raspberry-pi"},{default:r(()=>[...e[0]||(e[0]=[t("打印服務器",-1)])]),_:1}),e[2]||(e[2]=t("，可以在我的家庭網絡中共享激光打印機，或作為個人文件服務器保存項目副本和其他數據。",-1))]),e[34]||(e[34]=a('<p>我的文件服務器有很多用途。假設説我現在有一個項目，比如一本新書，我想把我的工作和所有相關的文件都複製一份快照。這種場景下，我只需要把 <code>BookProject</code> 文件夾複製到文件服務器的 <code>BookBackup</code> 文件夾。</p><p>或者我現在正在清理我的本地文件時，發現一些我不需要的文件，但是我不確定是否要刪除，我會把它們複製到文件服務器的 <code>KeepForLater</code> 文件夾。這是我日常 Linux 系統中清除雜亂的文件，並將不常用的文件卸載到個人文件服務器上的方便方法。</p><p>用樹莓派或其他 Linux 系統搭建個人文件服務器不需要配置 NFS（<ruby>網絡文件系統<rt>Network File System</rt></ruby>&gt;）或 CIFS（<ruby>通用互聯網文件系統<rt>Common Internet File System</rt></ruby>）或改造其他的文件共享系統如 WebDAV。你可以很輕鬆的使用 SSH 來搭建遠程文件服務器。下面是教程。</p><h3 id="在遠程服務器上配置-sshd" tabindex="-1">在遠程服務器上配置 SSHD <a class="header-anchor" href="#在遠程服務器上配置-sshd" aria-label="Permalink to “在遠程服務器上配置 SSHD”">​</a></h3>',4)),s("p",null,[e[4]||(e[4]=t("你的 Linux 系統可能已經安裝了 SSH 守護進程（",-1)),e[5]||(e[5]=s("code",null,"sshd",-1)),e[6]||(e[6]=t("），甚至它已經默認運行了。如果沒有，你可以使用你 Linux 發行版本上的任何控制面板來輕鬆配置 SSH。我在樹莓派上運行了 ",-1)),o(l,{href:"https://arm.fedoraproject.org/"},{default:r(()=>[...e[3]||(e[3]=[t("Fedora ARM",-1)])]),_:1}),e[7]||(e[7]=t("，通過 Web 瀏覽器訪問樹莓派的 9090 端口，我可以遠程訪問控制面板。（在我的家庭網絡中，樹莓派的 IP 地址是 ",-1)),e[8]||(e[8]=s("code",null,"10.0.0.11",-1)),e[9]||(e[9]=t("，因此我連接的是 ",-1)),e[10]||(e[10]=s("code",null,"10.0.0.11:9090",-1)),e[11]||(e[11]=t("。）如果 SSH 守護進程沒有默認運行，你可以在控制面板的“服務”裏把它設置為開機啓動。",-1))]),e[35]||(e[35]=a('<p><img src="https://opensource.com/sites/default/files/uploads/fedora-server-control-panel-sshd.png" alt="sshd in the list of system services" title="sshd in the list of system services"></p><p>你可以在系統服務列表裏找到 <code>sshd</code>。</p><p><img src="https://opensource.com/sites/default/files/uploads/fedora-server-control-panel-sshd-service.png" alt="slider to activate sshd" title="slider to activate sshd"></p><p>如果 <code>sshd</code> 沒有開啓，點擊切換按鈕打開它。</p><h3 id="你有賬號嗎" tabindex="-1">你有賬號嗎？ <a class="header-anchor" href="#你有賬號嗎" aria-label="Permalink to “你有賬號嗎？”">​</a></h3><p>你需要有個遠程系統的賬號。它可以與你本地系統的賬號相同，也可以不同。</p><p>在流行的 Raspbian 發行版本上，默認的賬號名是 <code>pi</code>。但是其他的 Linux 發行版本可能需要你在安裝系統時就設置一個唯一的新用户。如果你不知道你的用户名，你可以用系統的控制面板創建一個。在我的樹莓派上，我創建了一個 <code>jhall</code> 賬號，與我日常用的 Linux 桌面機器的用户名相同。</p><p><img src="https://opensource.com/sites/default/files/uploads/fedora-server-control-panel-accounts_create-user.png" alt="Set up a new account on Fedora Server" title="Set up a new account on Fedora Server"></p><p>如果你用的是 Fedora 服務器，你可以點擊“創建新賬號”按鈕。</p><p><img src="https://opensource.com/sites/default/files/uploads/fedora-server-control-panel-accounts.png" alt="Set password or SSH key" title="Set password or SSH key"></p><p>不要忘記設置密碼或添加公鑰。</p><h3 id="可選-添加公鑰" tabindex="-1">可選：添加公鑰 <a class="header-anchor" href="#可選-添加公鑰" aria-label="Permalink to “可選：添加公鑰”">​</a></h3><p>如果你把公鑰添加到遠程 Linux 系統上，你就可以不使用密碼登錄。這一步是可選的；如果你願意，你仍可以用密碼登錄。</p><p>你可以在下面的文章中學到更多關於 SSH 密鑰的信息：</p>',14)),s("ul",null,[s("li",null,[o(l,{href:"https://linux.cn/article-11947-1.html"},{default:r(()=>[...e[12]||(e[12]=[t("SSH 密鑰管理工具",-1)])]),_:1})]),s("li",null,[o(l,{href:"https://linux.cn/article-9451-1.html"},{default:r(()=>[...e[13]||(e[13]=[t("用 Seahorse 對 SSH 密鑰進行圖形化管理",-1)])]),_:1})]),s("li",null,[o(l,{href:"https://opensource.com/article/19/4/gpg-subkeys-ssh-manage"},{default:r(()=>[...e[14]||(e[14]=[t("如何管理多個 SSH 密鑰",-1)])]),_:1})]),s("li",null,[o(l,{href:"https://opensource.com/article/19/4/gpg-subkeys-ssh"},{default:r(()=>[...e[15]||(e[15]=[t("使用 GPG 密鑰作為鑑權依據開啓 SSH 訪問",-1)])]),_:1})])]),e[36]||(e[36]=a('<h3 id="創建文件管理器的快捷方式" tabindex="-1">創建文件管理器的快捷方式 <a class="header-anchor" href="#創建文件管理器的快捷方式" aria-label="Permalink to “創建文件管理器的快捷方式”">​</a></h3><p>現在你已經在遠程系統上啓動 SSH 守護進程了，也設置了用户名和密碼，最後一步就是在你本地的文件管理器中創建一個快捷方式，地址映射到遠程 Linux 系統。我的桌面是 GNOME，但是在其他的 Linux 桌面上的基本操作步驟都是一樣的。</p><h4 id="建立初始連接" tabindex="-1">建立初始連接 <a class="header-anchor" href="#建立初始連接" aria-label="Permalink to “建立初始連接”">​</a></h4><p>在 GNOME 的文件管理器中，在左邊導航欄找到 “+其它位置” 按鈕。點擊它會出現一個 “連接到服務器” 提示框。在框中輸入遠程 Linux 服務器的地址，地址以 SSH 連接協議開頭。</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome-file-manager-other-locations.png" alt="Creating a shortcut in GNOME file manager" title="Creating a shortcut in GNOME file manager"></p><p>GNOME 文件管理器支持多種連接協議。要通過 SSH 進行連接，服務器地址請以 <code>sftp://</code> 或 <code>ssh://</code> 開頭。</p><p>如果你遠程 Linux 系統的用户名與本地的相同，那麼你只需要輸入服務器的地址和文件夾路徑就可以了。比如要連接到我的樹莓派的 <code>/home/jhall</code> 目錄，我輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sftp://10.0.0.11/home/jhall</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/gnome-file-manager-other-sftp.png" alt="GNOME file manager Connect to Server" title="GNOME file manager Connect to Server"></p><p>如果你遠程 Linux 系統的用户名與本地的不同，你可以在遠程系統地址前加 <code>@</code> 符號來指定遠程系統的用户名。要連接到遠程的 Raspbian 系統，你可能要輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sftp://pi@10.0.0.11/home/pi</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/gnome-file-manager-other-sftp-username.png" alt="GNOME file manager Connect to Server" title="GNOME file manager Connect to Server"></p><p>如果你沒有把公鑰添加到遠程服務器，那麼你需要輸入密碼。如果你已經添加，GNOME 文件管理器應該會自動打開遠程系統上的文件夾來讓你跳轉到不同的目錄。</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome-file-manager-remote-jhall.png" alt="GNOME file manager connection" title="GNOME file manager connection"></p><h4 id="創建一個快捷方式-之後就可以輕鬆連接服務器" tabindex="-1">創建一個快捷方式，之後就可以輕鬆連接服務器 <a class="header-anchor" href="#創建一個快捷方式-之後就可以輕鬆連接服務器" aria-label="Permalink to “創建一個快捷方式，之後就可以輕鬆連接服務器”">​</a></h4><p>在 GNOME 文件管理器中，這很簡單。右擊導航欄中遠程系統的名字，選擇“添加書籤”。這一步操作就創建了連接到遠程路徑的快捷方式。</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome-file-manager-remote-jhall-add-bookmark.png" alt="GNOME file manager - adding bookmark" title="GNOME file manager - adding bookmark"></p><p>如果你想把標籤中的快捷方式改成一個更容易記的名字，你可以右擊快捷方式選擇“重命名”。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>通過 SSH 連接到遠程 Linux 系統是很簡單的事。你可以用相同的方式連接到家庭文件服務器以外的其他系統。我還創建了一個能讓我立即訪問我的提供商 Web 服務器上的文件的快捷方式，和另一個能迅速打開我的項目服務器的文件夾的快捷方式。SSH 使它成為一個安全的連接；所有的傳輸都是加密的。當我通過 SSH 打開遠程的文件時，我可以像在本地操作一樣使用 GNOME 文件管理器輕鬆打開遠程文件。</p><hr>',21)),s("p",null,[e[17]||(e[17]=t("via: ",-1)),o(l,{href:"https://opensource.com/article/20/3/personal-file-server-ssh"},{default:r(()=>[...e[16]||(e[16]=[t("https://opensource.com/article/20/3/personal-file-server-ssh",-1)])]),_:1})]),s("p",null,[e[22]||(e[22]=t("作者：",-1)),o(l,{href:"https://opensource.com/users/jim-hall"},{default:r(()=>[...e[18]||(e[18]=[t("Jim Hall",-1)])]),_:1}),e[23]||(e[23]=t(" 選題：",-1)),o(l,{href:"https://github.com/lujun9972"},{default:r(()=>[...e[19]||(e[19]=[t("lujun9972",-1)])]),_:1}),e[24]||(e[24]=t(" 譯者：",-1)),o(l,{href:"https://github.com/lxbwolf"},{default:r(()=>[...e[20]||(e[20]=[t("lxbwolf",-1)])]),_:1}),e[25]||(e[25]=t(" 校對：",-1)),o(l,{href:"https://github.com/wxy"},{default:r(()=>[...e[21]||(e[21]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[28]||(e[28]=t("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[26]||(e[26]=[t("LCTT",-1)])]),_:1}),e[29]||(e[29]=t(" 原創編譯，",-1)),o(l,{href:"https://linux.cn/"},{default:r(()=>[...e[27]||(e[27]=[t("Linux中國",-1)])]),_:1}),e[30]||(e[30]=t(" 榮譽推出",-1))])])}const L=i(u,[["render",f]]);export{H as __pageData,L as default};
